import json, glob, os
results = {}
for seed_label, pattern in [('seed42', 'hellaswag_gen{}/results.json'), ('seed43', 'hellaswag_seed43_gen{}'), ('seed44', 'hellaswag_seed44_gen{}/results.json')]:
    results[seed_label] = {}
    for g in range(11):
        if seed_label == 'seed43':
            base = f'/root/spectral_collapse_ews/results/hellaswag_seed43_gen{g}'
            found = glob.glob(os.path.join(base, '**/results*.json'), recursive=True)
            if found:
                with open(found[0]) as f:
                    d = json.load(f)
                    results[seed_label][g] = d.get('results',d).get('hellaswag',d.get('hellaswag',{})).get('acc_norm,none','MISSING')
            else:
                results[seed_label][g] = 'NO_FILE'
        else:
            path = f'/root/spectral_collapse_ews/results/{pattern.format(g)}'
            if os.path.exists(path):
                with open(path) as f:
                    d = json.load(f)
                    results[seed_label][g] = d.get('hellaswag',{}).get('acc_norm,none','MISSING')
            else:
                results[seed_label][g] = 'NO_FILE'
print(json.dumps(results, indent=2))
